77	  const [checking, setChecking] = useState(true);
78	
79	  useEffect(() => {
80	    supabase.auth.getUser().then(({ data: { user } }) => {
81	      if (user) {
82	        const userType = user.user_metadata?.user_type;
83	        if (userType === 'hire') {
