13	        const checkUser = async () => {
14	            const { data: { user } } = await supabase.auth.getUser();
15	
16	            if (!user) {
17	                navigate('/login');
18	                return;
19	            }
20	
21	            // Check if user is a worker and has completed onboarding
22	            // We optimize by checking if they are 'hire' type in metadata first to avoid unnecessary DB calls if they are company trying to access worker routes (which shouldn't happen but good to be safe)
23	            if (user.user_metadata?.user_type === 'hire') {
24	                // ideally redirect to company dashboard
25	                navigate('/company/dashboard');
26	                return;
27	            }
28	
29	            // Check worker profile
30	            const { data: worker } = await supabase
31	                .from('workers')
32	                .select('onboarding_completed')
33	                .eq('id', user.id)
34	                .single();
35	
36	            if (!worker || !worker.onboarding_completed) {
37	                navigate('/worker/onboarding');
38	            }
39	
40	            setLoading(false);
41	        };
42	
43	        checkUser();
44	    }, [navigate]);
45	
46	    if (loading) {
47	        return (
48	            <div className="min-h-screen flex flex-col md:flex-row max-w-7xl mx-auto bg-[#F4F4F0]">
49	                <div className="hidden md:block w-64 p-6 space-y-4">
