57	                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
58	                        {[...Array(3)].map((_, i) => <div key={i} className="h-28 bg-gray-200 rounded-xl animate-pulse" />)}
59	                    </div>
60	                    <div className="space-y-3">
61	                        {[...Array(4)].map((_, i) => <div key={i} className="h-20 bg-gray-200 rounded-xl animate-pulse" />)}
62	                    </div>
63	                </main>
64	            </div>
65	        );
66	    }
67	
68	    return (
69	        <div className="min-h-screen flex flex-col md:flex-row max-w-7xl mx-auto">
70	            {/* Desktop Sidebar */}
71	            <Sidebar />
72	
73	            {/* Mobile Header (Optional, for Logo) */}
