75	                <h1 className="text-xl font-black text-primary tracking-tighter">Worki.</h1>
76	                <NotificationBell />
77	            </header>
78	
79	            {/* Main Content Area */}
80	            <main className="flex-1 p-4 md:p-8 pb-24 md:pb-8 overflow-y-auto">
81	                <Outlet />
82	            </main>
83	
84	            {/* Mobile Navigation */}
85	            <BottomNav type="worker" />
86	        </div>
87	    );
