29	interface JobCardProps {
30	    job: Job;
31	    isApplied: boolean;
32	    onApply: (jobId: string) => void;
33	    isApplying?: boolean;
34	    variant?: 'feed' | 'search'; // 'feed' for Dashboard (95% Match), 'search' for Jobs (Novo)
35	    matchScore?: number;
36	}
37	
38	export default function JobCard({
39	    job,
40	    isApplied,
41	    onApply,
42	    isApplying = false,
43	    variant = 'search',
44	    matchScore = 95
45	}: JobCardProps) {
46	    const calculateHours = (start?: string, end?: string, lunch: boolean = false) => {
47	        if (!start || !end) return { total: 0, work: 0 };
48	        const [startH, startM] = start.split(':').map(Number);
49	        const [endH, endM] = end.split(':').map(Number);
50	
51	        let total = (endH + endM / 60) - (startH + startM / 60);
52	        if (total < 0) total += 24; // Handle overnight
