1	import React, { createContext, useContext, useEffect, useState } from 'react';
2	import type { User } from '@supabase/supabase-js';
3	import * as Sentry from '@sentry/react';
4	import { supabase } from '../lib/supabase';
5	
6	interface AuthContextType {
7	    user: User | null;
8	    loading: boolean;
9	    signOut: () => Promise<void>;
10	}
11	
12	const AuthContext = createContext<AuthContextType | undefined>(undefined);
13	
14	export function AuthProvider({ children }: { children: React.ReactNode }) {
15	    const [user, setUser] = useState<User | null>(null);
16	    const [loading, setLoading] = useState(true);
17	
18	    useEffect(() => {
19	        // Check active sessions and sets the user
20	        const getSession = async () => {
21	            const { data: { session } } = await supabase.auth.getSession();
22	            setUser(session?.user ?? null);
23	            if (session?.user) {
24	                Sentry.setUser({ id: session.user.id });
25	            } else {
26	                Sentry.setUser(null);
27	            }
28	            setLoading(false);
29	        };
30	
31	        getSession();
32	
33	        // Listen for changes on auth state (logged in, signed out, etc.)
34	        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
35	            setUser(session?.user ?? null);
36	            if (session?.user) {
37	                Sentry.setUser({ id: session.user.id });
38	            } else {
39	                Sentry.setUser(null);
40	            }
41	            setLoading(false);
42	        });
43	
44	        return () => subscription.unsubscribe();
45	    }, []);
46	
47	    const signOut = async () => {
48	        await supabase.auth.signOut();
49	        setUser(null);
50	    };
51	
52	    return (
53	        <AuthContext.Provider value={{ user, loading, signOut }}>
54	            {children}
55	        </AuthContext.Provider>
56	    );
57	}
58	
59	// eslint-disable-next-line react-refresh/only-export-components
60	export const useAuth = () => {
61	    const context = useContext(AuthContext);
62	    if (context === undefined) {
63	        throw new Error('useAuth must be used within an AuthProvider');
64	    }
65	    return context;
66	};
