1	import React, { createContext, useContext, useState, useCallback } from 'react';
2	import { X, CheckCircle, AlertCircle, Info } from 'lucide-react';
3	
4	export type ToastType = 'success' | 'error' | 'info';
5	
6	interface Toast {
7	    id: string;
8	    message: string;
9	    type: ToastType;
10	}
11	
12	interface ToastContextType {
13	    addToast: (message: string, type?: ToastType) => void;
14	    removeToast: (id: string) => void;
15	}
16	
17	const ToastContext = createContext<ToastContextType | undefined>(undefined);
18	
19	export function ToastProvider({ children }: { children: React.ReactNode }) {
20	    const [toasts, setToasts] = useState<Toast[]>([]);
21	
22	    const removeToast = useCallback((id: string) => {
23	        setToasts((prev) => prev.filter((toast) => toast.id !== id));
24	    }, []);
25	
26	    const addToast = useCallback((message: string, type: ToastType = 'info') => {
27	        const id = Math.random().toString(36).substring(7);
28	        setToasts((prev) => [...prev, { id, message, type }]);
29	
30	        // Auto remove after 3 seconds
31	        setTimeout(() => {
32	            removeToast(id);
33	        }, 3000);
34	    }, [removeToast]);
35	
36	    return (
37	        <ToastContext.Provider value={{ addToast, removeToast }}>
38	            {children}
39	            <div className="fixed bottom-4 right-4 z-50 flex flex-col gap-2 pointer-events-none">
40	                {toasts.map((toast) => (
41	                    <div
42	                        key={toast.id}
43	                        className={`
44	              pointer-events-auto flex items-center gap-3 px-4 py-3 rounded-xl shadow-lg border-2 animate-in slide-in-from-right-full duration-300
45	              ${toast.type === 'success' ? 'bg-green-50 border-green-500 text-green-900' : ''}
46	              ${toast.type === 'error' ? 'bg-red-50 border-red-500 text-red-900' : ''}
47	              ${toast.type === 'info' ? 'bg-blue-50 border-blue-500 text-blue-900' : ''}
48	            `}
49	                    >
50	                        {toast.type === 'success' && <CheckCircle size={20} className="text-green-500" />}
51	                        {toast.type === 'error' && <AlertCircle size={20} className="text-red-500" />}
52	                        {toast.type === 'info' && <Info size={20} className="text-blue-500" />}
53	
54	                        <p className="font-bold text-sm">{toast.message}</p>
55	
56	                        <button
57	                            onClick={() => removeToast(toast.id)}
