5	export const AnalyticsService = {
6	    /**
7	     * Tracks a view on a job posting.
8	     * Increments the 'views' counter on the job and logs an event.
9	     */
10	    async trackJobView(jobId: string) {
11	        try {
12	            const { data: { user } } = await supabase.auth.getUser();
13	            if (!user) return; // Only track authenticated users for now
14	
15	            // 1. Increment Counter (RPC)
16	            // We use rpc to be atomic
17	            const { error: rpcError } = await supabase.rpc('increment_job_view', { job_id: jobId });
18	
19	            if (rpcError) {
20	                logWarn('Analytics: increment_job_view RPC failed (may not exist yet):', rpcError.message);
21	            }
22	
23	            // 2. Log Granular Event
24	            const { error: eventError } = await supabase
25	                .from('analytics_events')
26	                .insert({
27	                    user_id: user.id,
28	                    event_type: 'view_job',
29	                    target_id: jobId,
30	                    metadata: { timestamp: new Date().toISOString() }
31	                });
32	
33	            if (eventError) {
34	                // Silently fail if table doesn't exist yet
35	                console.debug('Analytics: Event log failed:', eventError.message);
36	            }
37	
38	        } catch (error) {
39	            logError('Analytics Error:', error);
40	        }
41	    },
42	
43	    /**
44	     * Tracks a view on a worker's public profile.
45	     * Increments the 'views' counter on the profile and logs an event.
46	     */
47	    async trackProfileView(workerId: string) {
48	        try {
49	            const { data: { user } } = await supabase.auth.getUser();
50	            if (!user) return;
51	            if (user.id === workerId) return; // Don't track self-views
52	
53	            // 1. Increment Counter (RPC)
54	            const { error: rpcError } = await supabase.rpc('increment_worker_view', { worker_id: workerId });
55	
56	            if (rpcError) {
57	                logWarn('Analytics: increment_worker_view RPC failed:', rpcError.message);
58	            }
59	
60	            // 2. Log Granular Event
61	            const { error: eventError } = await supabase
62	                .from('analytics_events')
63	                .insert({
64	                    user_id: user.id,
65	                    event_type: 'view_profile',
66	                    target_id: workerId,
67	                    metadata: { timestamp: new Date().toISOString() }
68	                });
69	
70	            if (eventError) console.debug('Analytics: Event log failed:', eventError.message);
71	
72	        } catch (error) {
73	            logError('Analytics Error:', error);
74	        }
75	    },
