4	export const LEVELS = [
5	    { level: 1, minXp: 0 },
6	    { level: 2, minXp: 100 },
7	    { level: 3, minXp: 300 },
8	    { level: 4, minXp: 600 },
9	    { level: 5, minXp: 1000 },
10	    { level: 6, minXp: 1500 },
11	    { level: 7, minXp: 2100 },
12	    { level: 8, minXp: 2800 },
13	    { level: 9, minXp: 3600 },
14	    { level: 10, minXp: 4500 },
15	];
16	
17	export const calculateLevel = (xp: number) => {
18	    for (let i = LEVELS.length - 1; i >= 0; i--) {
19	        if (xp >= LEVELS[i].minXp) {
20	            return LEVELS[i].level;
21	        }
22	    }
23	    return 1;
24	};
