26	export const addXP = async (userId: string, amount: number) => {
27	    try {
28	        // Get current XP
29	        const { data: worker, error: fetchError } = await supabase
30	            .from('workers')
31	            .select('xp')
32	            .eq('id', userId)
33	            .single();
34	
35	        if (fetchError) throw fetchError;
36	
37	        const currentXp = worker.xp || 0;
38	        const newXp = currentXp + amount;
39	        const newLevel = calculateLevel(newXp);
40	
41	        // Update XP and Level
42	        const { error: updateError } = await supabase
43	            .from('workers')
44	            .update({
45	                xp: newXp,
46	                level: newLevel
47	            })
48	            .eq('id', userId);
49	
50	        if (updateError) throw updateError;
51	
52	        return { newXp, newLevel };
53	    } catch (error) {
54	        logError('Error adding XP:', error);
55	        return null;
56	    }
57	};
