1	/**
2	 * Funcoes de validacao reutilizaveis para CPF, CNPJ, email e forca de senha.
3	 */
4	
5	/** Valida CPF (somente digitos, 11 chars) */
6	export function validateCPF(cpf: string): boolean {
7	    if (cpf.length !== 11 || /^(\d)\1{10}$/.test(cpf)) return false;
8	    const d = cpf.split('').map(Number);
9	    let s = 0;
10	    for (let i = 0; i < 9; i++) s += d[i] * (10 - i);
11	    let r = (s * 10) % 11; if (r === 10) r = 0;
12	    if (r !== d[9]) return false;
13	    s = 0;
14	    for (let i = 0; i < 10; i++) s += d[i] * (11 - i);
15	    r = (s * 10) % 11; if (r === 10) r = 0;
16	    return r === d[10];
17	}
18	
19	/** Valida CNPJ (aceita com ou sem formatacao) */
20	export function validateCNPJ(cnpj: string): boolean {
21	    const clean = cnpj.replace(/\D/g, '');
22	    if (clean.length !== 14 || /^(\d)\1{13}$/.test(clean)) return false;
23	    const d = clean.split('').map(Number);
24	    const w1 = [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
25	    const w2 = [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
26	    let s = 0;
27	    for (let i = 0; i < 12; i++) s += d[i] * w1[i];
28	    let r = s % 11;
29	    if ((r < 2 ? 0 : 11 - r) !== d[12]) return false;
30	    s = 0;
31	    for (let i = 0; i < 13; i++) s += d[i] * w2[i];
32	    r = s % 11;
33	    return (r < 2 ? 0 : 11 - r) === d[13];
34	}
