36	export const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
37	
38	/** Valida formato de email */
39	export function validateEmail(email: string): boolean {
40	    return EMAIL_REGEX.test(email);
41	}
