43	export interface PasswordStrength {
44	    label: string;
45	    color: string;
46	    width: string;
47	    score: number;
48	}
49	
50	/** Avalia forca da senha */
51	export function getPasswordStrength(pw: string): PasswordStrength {
52	    let score = 0;
53	    if (pw.length >= 8) score++;
54	    if (pw.length >= 12) score++;
55	    if (/[a-z]/.test(pw) && /[A-Z]/.test(pw)) score++;
56	    if (/\d/.test(pw)) score++;
57	    if (/[^a-zA-Z0-9]/.test(pw)) score++;
58	
59	    if (score <= 1) return { label: 'Fraca', color: 'bg-red-500', width: 'w-1/4', score };
60	    if (score <= 2) return { label: 'Razoavel', color: 'bg-yellow-500', width: 'w-1/2', score };
61	    if (score <= 3) return { label: 'Media', color: 'bg-blue-500', width: 'w-3/4', score };
62	    return { label: 'Forte', color: 'bg-green-500', width: 'w-full', score };
63	}
